    52	/// Bound, optimized DuckDB logical plan (Substrait bytes, SQL, …).
    53	using logical_plan_source =
    54	  std::function<duckdb::unique_ptr<duckdb::LogicalOperator>(duckdb::ClientContext&)>;
    55	
    56	struct fragment_spec {
    57	  logical_plan_source plan_source;
    58	  std::map<stream_id_t, stream_input_spec> inputs;
    59	  /// Positional: outputs[i] addresses partition i.
    60	  std::vector<stream_id_t> outputs;
    61	  /// Absent = gather (single destination, no partitioning).
    62	  std::optional<op::partition_spec> partitioning;
    63	  /// Telemetry identity of the fragment's query: `query_label` becomes the Quent Query
    64	  /// `instance_name` (absent = "sirius_streaming_fragment"), `session_label` selects the
    65	  /// QueryGroup it joins (absent = the engine's default group). An embedding sets both to the
    66	  /// distributed query's ids so fragments on different processes line up under one label.
    67	  std::optional<std::string> query_label;
    68	  std::optional<std::string> session_label;
    69	};
