    71	/// Owns repos/engine/session for one fragment.
    72	/// Repositories escape data_repository_manager_ cleanup (survive the query window).
    73	/// Engine owns the plan so the sink stays pullable after run().
    74	class streaming_fragment {
    75	 public:
    76	  /// Validates the spec and creates one repository per declared stream.
    77	  /// @throws sirius::invalid_input_exception when plan_source is unset, outputs empty, N>1
    78	  ///         without partitioning, or on a duplicate output id.
    79	  streaming_fragment(duckdb::ClientContext& context, fragment_spec spec);
    80	
    81	  /// Clears this fragment's declarations from the connection's stream_bind_catalog.
    82	  ~streaming_fragment();
    83	
    84	  streaming_fragment(const streaming_fragment&)            = delete;
    85	  streaming_fragment& operator=(const streaming_fragment&) = delete;
    86	
