/// The remote drains one sender fragment posted to the transport thread, not yet joined.
#[must_use = "unjoined drains discard the failures the FE has to see"]
#[derive(Debug, Default)]
struct SenderDrains(Vec<DrainTicket>);

impl SenderDrains {
    fn push(&mut self, ticket: DrainTicket) {
        self.0.push(ticket);
    }

    /// Joins EVERY drain and returns the first failure.
    ///
    /// Never short-circuits on the first error, for two reasons. (1) A posted drain runs to
    /// completion on the transport thread whatever this thread does, and it is that drain — not
    /// this code — that performs the exactly-once `drop_parked` releasing its destination's
    /// claim on the parked fragment (nixl_transport.rs:669 on success, :306-317 on failure);
    /// abandoning a sibling would only lose its outcome, never cancel it. (2) The FE must see a
    /// failure whichever destination produced it. Every failure is logged; the first is returned.
    fn join(self) -> std::result::Result<(), String> {
        let mut first = None;
        for ticket in self.0 {
            if let Err(err) = ticket.join() {
                tracing::error!(error = %err, "a remote destination's drain failed");
                first.get_or_insert(err);
            }
        }
        first.map_or(Ok(()), Err)
    }
}

/// What processing one fragment produced: the receivers whose sender sets it completed, and the
/// remote drains it posted. The two are deliberately separate so a caller can dispatch the
/// receivers *before* it joins the drains.
#[must_use]
#[derive(Debug, Default)]
struct FragmentOutcome {
    ready: Vec<ReadyFragment>,
    drains: SenderDrains,
}

impl FragmentOutcome {
    /// A fragment that readied receivers but posted no remote drain.
    fn from_ready(ready: Vec<ReadyFragment>) -> Self {
        Self {
            ready,
            drains: SenderDrains::default(),
        }
    }

    /// Joins the drains first, then yields the ready receivers — the shape the dispatch worker
    /// needs.
    ///
    /// The worker is single-threaded and is itself the thread that would run those receivers, so
    /// deferring the join there would buy no overlap; it would only move a drain failure out of
    /// `run_ready_fragment`, which is where a fragment failure gets attributed to its query. The
    /// overlap lives on the RPC path (`dispatch_then_join`), where the receiver runs on a
    /// different thread from the one that joins. Dropping `ready` when a drain failed matches
    /// the blocking loop this replaces: a sender that could not reach a remote destination has
    /// already failed the query.
    fn join_into_ready(self) -> std::result::Result<Vec<ReadyFragment>, String> {
        self.drains.join()?;
        Ok(self.ready)
    }
}

/// Sirius compute-node implementation of StarRocks PInternalService.
///
/// Plan-fragment translation is the first implemented RPC path; future
/// compute-node tasks should land here behind the generated service facade.
#[derive(Clone, Debug)]
pub(crate) struct SiriusComputeNodeService {
    /// Fragment-processing state shared across BRPC connections and the dispatch worker.
    core: Arc<ServiceCore>,
    /// Hands ready receiver fragments to the dispatch worker instead of executing them on the
    /// RPC thread that completed the sender set.
    ready_fragments: mpsc::Sender<ReadyFragment>,
}

/// Shared state behind every clone of [`SiriusComputeNodeService`].
///
/// One `Arc` so a `fetch_data` poll on one BRPC connection sees what an `exec_plan_fragment` on
/// another buffered — and so the dispatch worker holds the state (executor included) without
/// holding a `ready_fragments` sender, letting the channel close and the worker exit when the
/// last service clone drops. That keeps engine teardown ordered behind the servers.
#[derive(Debug)]
struct ServiceCore {
    /// Reusable StarRocks thrift-to-Substrait fragment translator.
    translator: PlanTranslator,
    /// Executes a translated fragment into Arrow result batches. Production injects the GPU-backed
    /// `SiriusEngine` (via [`SiriusComputeNodeService::with_executor`]); tests use a stub.
    executor: Arc<dyn FragmentExecutor>,
    /// Buffers executed-fragment results for FE `fetch_data` collection.
    results: ResultStore,
    /// Sequential same-node fragment exchange state.
    exchanges: LocalExchange,
    /// StarRocks may send a descriptor table once per query and mark later fragments as cached.
    descriptor_tables: Mutex<HashMap<FragmentInstanceId, TDescriptorTable>>,
    /// The exchange endpoint this CN advertises; destinations matching it are local.
    identity: ExchangeIdentity,
    /// The nixl transport tier for remote destinations. `None` keeps every remote destination a
    /// loud error naming how to enable it.
    transport: Option<NixlTransport>,
    /// Staging arena `(base, capacity)`, cached after the first lookup (the arena never moves).
    /// The executor serves every staging call from a thread-safe arena handle, never from the
    /// engine's request queue, so a lease request costs a mutex — not an engine wait.
    staging_info: Mutex<Option<(u64, u64)>>,
    /// Whether sender-only fragments are queued on the dispatch worker instead of running inside
    /// their exec_plan_fragment RPC. Off unless `SIRIUS_CN_ASYNC_SENDER_DISPATCH` is set at
    /// bring-up (or a test flips it); see [`SiriusComputeNodeService::try_dispatch_sender`].
    async_sender_dispatch: std::sync::atomic::AtomicBool,
}

impl SiriusComputeNodeService {
    /// Test-only constructor with the placeholder [`StubExecutor`] and the default local
    /// identity. Production injects everything via [`with_transport`](Self::with_transport).
    #[cfg(test)]
    pub(crate) fn new() -> Self {
        Self::with_executor(
            Arc::new(StubExecutor),
            ExchangeIdentity::new("127.0.0.1", 8060),
        )
    }

    /// [`with_transport`](Self::with_transport) without a nixl transport: every remote
    /// destination stays a loud error.
    #[cfg(test)]
    pub(crate) fn with_executor(
        executor: Arc<dyn FragmentExecutor>,
        identity: ExchangeIdentity,
    ) -> Self {
        Self::with_transport(executor, identity, None)
    }

    /// Builds the service with a caller-provided fragment executor (e.g. the GPU-backed
    /// `SiriusEngine`), this CN's advertised exchange identity, and an optional nixl transport
    /// for remote destinations, shared across BRPC connections via the `Arc`. Also spawns the
    /// fragment dispatch worker.
    pub(crate) fn with_transport(
        executor: Arc<dyn FragmentExecutor>,
        identity: ExchangeIdentity,
        transport: Option<NixlTransport>,
    ) -> Self {
        let core = Arc::new(ServiceCore {
            translator: PlanTranslator::new(),
            executor,
            results: ResultStore::default(),
            exchanges: LocalExchange::default(),
            descriptor_tables: Mutex::new(HashMap::new()),
            identity,
            transport,
            staging_info: Mutex::new(None),
            async_sender_dispatch: std::sync::atomic::AtomicBool::new(
                Self::async_sender_dispatch_from_env(),
            ),
        });
        // A dedicated thread with a std channel (not a tokio task): fragment execution is
        // synchronous and blocking, so it gets the same dedicated-thread shape as the engine
        // itself, and the BRPC current-thread runtime is never involved.
        let (ready_fragments, worker_inbox) = mpsc::channel();
        let worker_core = Arc::clone(&core);
        std::thread::Builder::new()
            .name("fragment-dispatch".to_string())
            .spawn(move || dispatch_worker(worker_core, worker_inbox))
            .expect("failed to spawn fragment dispatch worker");
        Self {
            core,
            ready_fragments,
        }
    }

    /// Reads `SIRIUS_CN_ASYNC_SENDER_DISPATCH` once at bring-up: `1`, `true` or `on` queue
    /// sender-only fragments (no exchange input, no RESULT_SINK) on the dispatch worker instead of
    /// running them inside their exec_plan_fragment RPC. Off by default.
    ///
    /// Why it exists: the FE deploys the first fragment instance of every node in one wave and
    /// waits for all of those RPCs before it deploys the remaining instances. A sender that runs
    /// inside its RPC holds that wave open for its whole scan, so on a gather (q06: partial ->
    /// EXCHANGE UNPARTITIONED) the node that also hosts the merge fragment only receives its own
    /// scan after every other node's scan has finished. Measured on 4 GB200 CNs at SF1000: three
    /// scans started together and the fourth 726 ms later, right after the last `transmitted
    /// batches via nixl`. Returning as soon as the fragment is queued lets every scan start in the
    /// same wave.
    ///
    /// Why it is off by default: a queued sender's failure (a malformed sink, an untranslatable
    /// plan, a failed remote drain) is attributed through `results.fail_query`, which only reaches
    /// result instances reserved on this node. When the result fragment lives on another node the
    /// FE learns of the failure through its query timeout instead of this RPC's status. Flip the
    /// default once a sender failure is forwarded to the receiver's node.
    fn async_sender_dispatch_from_env() -> bool {
        matches!(
            std::env::var("SIRIUS_CN_ASYNC_SENDER_DISPATCH").as_deref(),
            Ok("1") | Ok("true") | Ok("TRUE") | Ok("on") | Ok("ON")
        )
    }

    /// Overrides the bring-up setting; tests use it to exercise the queued path without touching
    /// the process environment.
    #[cfg(test)]
    pub(crate) fn set_async_sender_dispatch(&self, enabled: bool) {
        self.core
            .async_sender_dispatch
            .store(enabled, std::sync::atomic::Ordering::Relaxed);
    }

    /// Queues a sender-only fragment on the dispatch worker. Returns `Ok(false)` when the
    /// fragment must take the inline path (exchange receiver, RESULT_SINK root, survey mode, or
    /// the switch is off); descriptor tables are resolved at arrival either way, so the FE's
    /// per-query descriptor cache protocol sees the same order as before.
    fn try_dispatch_sender(
        &self,
        params: &TExecPlanFragmentParams,
    ) -> std::result::Result<bool, String> {
        if !self
            .core
            .async_sender_dispatch
            .load(std::sync::atomic::Ordering::Relaxed)
            || std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some()
            || !ServiceCore::receiver_exchanges(params)?.is_empty()
            || ServiceCore::is_mysql_result_sink(params)?
        {
            return Ok(false);
        }
        let params = self.core.resolve_descriptor_table(params)?;
        self.dispatch(ReadyFragment {
            params,
            inputs: Vec::new(),
        })?;
        Ok(true)
    }

    /// Hands a ready receiver to the dispatch worker so this RPC thread returns immediately
    /// instead of blocking on the receiver's whole execution.
    fn dispatch(&self, ready: ReadyFragment) -> std::result::Result<(), String> {
        self.ready_fragments.send(ready).map_err(|_| {
            "fragment dispatch worker has exited; cannot execute receiver fragment".to_string()
        })
    }

    /// Dispatches every receiver this fragment readied, THEN joins its remote drains.
    ///
    /// The order is the whole change: dispatch puts the receiver on the worker thread while the
    /// transport thread is still draining this sender's remote destinations, instead of the
    /// receiver waiting out the full (N-1)-destination drain first. The RPC still does not
    /// return until every drain has been joined — the FE may only be told the sender succeeded
    /// once each destination's copy is actually across the wire.
    ///
    /// A receiver dispatched here can now run concurrently with its own query's drains. That
    /// costs nothing in correctness (its sender set was already complete, so it reads no data
    /// the drains produce) but it does mean the parked batches of the not-yet-drained
    /// destinations stay resident while it computes — the deliberate memory-for-latency trade.
    fn dispatch_then_join(&self, outcome: FragmentOutcome) -> std::result::Result<(), String> {
        let mut dispatch_error = None;
        for ready in outcome.ready {
            if let Err(err) = self.dispatch(ready) {
                dispatch_error.get_or_insert(err);
            }
        }
        // Joined unconditionally, even when dispatch failed: the drains are already in flight.
        let drain_result = outcome.drains.join();
        match (drain_result, dispatch_error) {
            (Ok(()), None) => Ok(()),
            (Ok(()), Some(dispatch)) => Err(dispatch),
            // A drain failure names the destination and the transport fault, so it is the more
            // useful cause to hand the FE; a dispatch failure only ever means "this CN is
            // shutting down". Report the drain error, keep the other in the log.
            (Err(drain), dispatch) => {
                if let Some(dispatch) = dispatch {
                    tracing::error!(error = %dispatch, "receiver dispatch also failed");
                }
                Err(drain)
            }
        }
    }
}

/// Executes ready receiver fragments sequentially, off the RPC threads.
///
/// Exits when every service clone has dropped its sender; the worker then releases its core
/// handle (and with it the executor), keeping engine teardown ordered.
fn dispatch_worker(core: Arc<ServiceCore>, inbox: mpsc::Receiver<ReadyFragment>) {
    while let Ok(ready) = inbox.recv() {
        // A receiver can itself be a sender whose completion readies further receivers (a
        // middle fragment, possibly fanning out); chase the whole set inline — this thread is
        // already off the RPC path.
        let mut queue = vec![ready];
        while let Some(ready) = queue.pop() {
            queue.extend(core.run_ready_fragment(ready));
        }
    }
}

